static void gerrit_scan_text(const char *text, notify_source_t src,
                             long *last_max, int *n_new)
{
    const char *p = text;

    while (p && *p) {
        const char *eol = strchr(p, '\n');
        size_t len = eol ? (size_t)(eol - p) : strlen(p);

        /* "- <digits>: subject" */
