                /* Cap toasts per poll; last_max still advances so the
                 * skipped backlog is not re-reported next time. */
                if (*n_new < AGENT_NOTIFY_MAX_NEW) {
                    push_notify(src, key, summary);
                    (*n_new)++;
                }
                *last_max = id;
            }
        }
        p = eol ? eol + 1 : NULL;
    }
}

